CREATE OR REPLACE FUNCTION public.service_profile_data(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p.published OR p.user_id=auth.uid() THEN jsonb_build_object('profile',to_jsonb(p),'photos',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM service_photos f WHERE f.user_id=p.user_id),'[]'::jsonb),'reviews',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'rating',r.rating,'body',r.body,'created_at',r.created_at,'author_name',coalesce(a.display_name,''),'author_photo',coalesce(a.photo_path,''),'author_public_id',a.user_id) ORDER BY r.created_at DESC) FROM service_reviews r LEFT JOIN service_profiles a ON a.user_id=r.author_id AND a.published WHERE r.profile_id=p.user_id),'[]'::jsonb),'likes',(SELECT count(*) FROM service_likes l WHERE l.profile_id=p.user_id),'views',(SELECT count(*) FROM service_views v WHERE v.profile_id=p.user_id)) ELSE NULL END FROM service_profiles p WHERE p.user_id=_id $$;